## Solution - Weird Algorithm

```cpp
#include <iostream>
using namespace std;

int main() {
	long long x;
	cin >> x;
	while (x != 1) {
		cout << x << " ";
		if (x % 2 == 0) {
			x /= 2;
		} else {
			x = 3 * x + 1;
		}
	}
	cout << x << endl;
}
```

