### Solution 2 - Greedy

Just keep matching a leaf with the only vertex adjacent to it while possible.

```cpp
int n;
vi adj[MX];
bool done[MX];
int ans = 0;

void dfs(int pre, int cur) {
	for (int i : adj[cur]) {
		if (i != pre) {
			dfs(cur, i);
			if (!done[i] && !done[cur]) done[cur] = done[i] = 1, ans++;
		}
	}
}

