## 2D BIT

### Tutorial

	- [2D BIT](two-dimensional-binary-indexed-tree-or-fenwick-tree) (GFG)
	- [Binary Indexed Trees](binary-indexed-trees) (TC)

### Implementation

Essentially, we just nest the loops that one would find in a 1D BIT to get
N-dimensional BITs. We can then use
[PIE](https://brilliant.org/wiki/principle-of-inclusion-and-exclusion-pie/) to
query subrectangles.

```cpp
#include <iostream>
#include <vector>
using namespace std;

/**
 * 2D Fenwick Tree implementation.
 * Note that all cell locations are zero-indexed
 * in this implementation.
 */
template <typename T> class BIT2D {
  private:
	const int n, m;
	vector<vector> bit;

  public:
	BIT2D(int n, int m) : n(n), m(m), bit(n + 1, vector(m + 1)) {}

	/** adds val to the point (r, c) */
	void add(int r, int c, T val) {
		r++, c++;
		for (; r <= n; r += r & -r) {
			for (int i = c; i <= m; i += i & -i) { bit[r][i] += val; }
		}
	}

	/** @returns sum of points with row in [0, r] and column in [0, c] */
	T rect_sum(int r, int c) {
		r++, c++;
		T sum = 0;
		for (; r > 0; r -= r & -r) {
			for (int i = c; i > 0; i -= i & -i) { sum += bit[r][i]; }
		}
		return sum;
	}

	/** @returns sum of points with row in [r1, r2] and column in [c1, c2] */
	T rect_sum(int r1, int c1, int r2, int c2) {
		return rect_sum(r2, c2) - rect_sum(r2, c1 - 1) - rect_sum(r1 - 1, c2) +
		       rect_sum(r1 - 1, c1 - 1);
	}
};

int main() {
	int n, q;
	cin >> n >> q;
	BIT2D<int> bit(n, n);
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			char c;
			cin >> c;
			if (c == '*') { bit.add(i, j, 1); }
		}
	}

	for (int i = 0; i < q; i++) {
		int type;
		cin >> type;
		if (type == 1) {
			int r, c;
			cin >> r >> c;
			r--, c--;
			if (bit.rect_sum(r, c, r, c) == 1) {
				bit.add(r, c, -1);
			} else {
				bit.add(r, c, 1);
			}
		} else if (type == 2) {
			int r1, c1, r2, c2;
			cin >> r1 >> c1 >> r2 >> c2;
			r1--, c1--, r2--, c2--;
			cout << bit.rect_sum(r1, c1, r2, c2) << '\n';
		}
	}
}
```

### Alternative Implementation

Using the multidimensional implementation mentioned
[here](https://usaco.guide/gold/PURS/#resources-1).

```cpp
template <class T, int... Ns> struct BIT {
	T val = 0;
	void upd(T v) { val += v; }
	T query() { return val; }
};

template <class T, int N, int... Ns> struct BIT<T, N, Ns...> {
	BIT<T, Ns...> bit[N + 1];
	template <typename... Args> void upd(int pos, Args... args) {
		for (; pos <= N; pos += (pos & -pos)) bit[pos].upd(args...);
	}
	template <typename... Args> T sum(int r, Args... args) {
		T res = 0;
		for (; r; r -= (r & -r)) res += bit[r].query(args...);
		return res;
	}
	template <typename... Args> T query(int l, int r, Args... args) {
		return sum(r, args...) - sum(l - 1, args...);
	}
};  // BIT<int,10,10> gives a 2D BIT

BIT<int, 1000, 1000> B;
int n, q;

int main() {
	setIO();
	re(n, q);
	F0R(i, n) {
		string s;
		re(s);
		F0R(j, n) if (s[j] == '*') B.upd(i + 1, j + 1, 1);
	}
	F0R(i, q) {
		int t;
		re(t);
		if (t == 1) {
			int y, x;
			re(y, x);
			if (B.query(y, y, x, x)) B.upd(y, x, -1);
			else B.upd(y, x, 1);
		} else {
			int y1, x1, y2, x2;
			re(y1, x1, y2, x2);
			ps(B.query(y1, y2, x1, x2));
		}
	}
}
```

