	}
};
// EndCodeSnip

int main() {
	int n;
	cin >> n;
	vector points(n);
	for (auto &p : points) { cin >> p; }
	points.push_back(points[0]);

	long long area = 0;
	for (int i = 0; i < n; i++) {
