## Monkey and Apple-trees

### Solution

We need to support two operations on a range:

- Count the number of red-ripe trees in a range (range sum)
- Set all trees in a range to red-ripe (range paint)

We can use a segment tree with lazy propagation to solve this, but the query
range is up to $10^9$, so we have to use a sparse segment tree.

Luckily, lazy propagation still works here.

### Pointer Implementation

**Time Complexity:** $\mathcal{O}(Q\log{N})$

```cpp
#include <bits/stdc++.h>
using namespace std;

class SparseSegtree {
  private:
	struct Node {
		int freq = 0;
		int lazy = 0;
		Node *left = nullptr;
		Node *right = nullptr;
	};
	Node *root = new Node;
	const int n;

	int comb(int a, int b) { return a + b; }

	void apply(Node *cur, int len, int val) {
		if (val == 1) {
			(cur->lazy) = val;
			(cur->freq) = len * val;
		}
	}

	void push_down(Node *cur, int l, int r) {
		if ((cur->left) == nullptr) { (cur->left) = new Node; }
		if ((cur->right) == nullptr) { (cur->right) = new Node; }
		int m = (l + r) / 2;
		apply(cur->left, m - l + 1, cur->lazy);
		apply(cur->right, r - m, cur->lazy);
	}

	void range_set(Node *cur, int l, int r, int ql, int qr, int val) {
		if (qr < l || ql > r) { return; }
		if (ql <= l && r <= qr) {
			apply(cur, r - l + 1, val);
		} else {
			push_down(cur, l, r);
			int m = (l + r) / 2;
			range_set(cur->left, l, m, ql, qr, val);
			range_set(cur->right, m + 1, r, ql, qr, val);
			(cur->freq) = comb((cur->left)->freq, (cur->right)->freq);
		}
	}

	int range_sum(Node *cur, int l, int r, int ql, int qr) {
		if (qr < l || ql > r) { return 0; }
		if (ql <= l && r <= qr) { return cur->freq; }
		push_down(cur, l, r);
		int m = (l + r) / 2;
		return comb(range_sum(cur->left, l, m, ql, qr),
		            range_sum(cur->right, m + 1, r, ql, qr));
	}

  public:
	SparseSegtree(int n) : n(n) {}

	void range_set(int ql, int qr, int val) { range_set(root, 0, n - 1, ql, qr, val); }

	int range_sum(int ql, int qr) { return range_sum(root, 0, n - 1, ql, qr); }
};

int main() {
	int query_num;
	cin >> query_num;
	const int RANGE_SIZE = 1e9;
	SparseSegtree st(RANGE_SIZE + 1);

	int c = 0;
	for (int i = 0; i < query_num; i++) {
		int type, x, y;
		cin >> type >> x >> y;
		if (type == 1) {
			c = st.range_sum(x + c, y + c);
			cout << c << '\n';
		} else if (type == 2) {
			st.range_set(x + c, y + c, 1);
		}
	}
}
```

> This implementation is not garbage collected, so the tree nodes aren't deleted even if the instance
> of the segment tree is taken out of scope.

### Index Implementation

**Time Complexity:** $\mathcal{O}(Q\log{N})$

```cpp
#include <bits/stdc++.h>
using namespace std;

class SparseSegtree {
  private:
	struct Node {
		int freq = 0;
		int lazy = 0;
		int left = -1;
		int right = -1;
	};
	vector tree;
	const int n;
	int timer = 0;

	int comb(int a, int b) { return a + b; }

	void apply(int cur, int len, int val) {
		if (val == 1) {
			tree[cur].lazy = val;
			tree[cur].freq = len * val;
		}
	}

	void push_down(int cur, int l, int r) {
		if (tree[cur].left == -1) {
			tree[cur].left = ++timer;
			tree.push_back(Node());
		}
		if (tree[cur].right == -1) {
			tree[cur].right = ++timer;
			tree.push_back(Node());
		}
		int m = (l + r) / 2;
		apply(tree[cur].left, m - l + 1, tree[cur].lazy);
		apply(tree[cur].right, r - m, tree[cur].lazy);
		tree[cur].lazy = 0;
	}

	void range_set(int cur, int l, int r, int ql, int qr, int val) {
		if (qr < l || ql > r) { return; }
		if (ql <= l && r <= qr) {
			apply(cur, r - l + 1, val);
		} else {
			push_down(cur, l, r);
			int m = (l + r) / 2;
			range_set(tree[cur].left, l, m, ql, qr, val);
			range_set(tree[cur].right, m + 1, r, ql, qr, val);
			tree[cur].freq =
			    comb(tree[tree[cur].left].freq, tree[tree[cur].right].freq);
		}
	}

	int range_sum(int cur, int l, int r, int ql, int qr) {
		if (qr < l || ql > r) { return 0; }
		if (ql <= l && r <= qr) { return tree[cur].freq; }
		push_down(cur, l, r);
		int m = (l + r) / 2;
		return comb(range_sum(tree[cur].left, l, m, ql, qr),
		            range_sum(tree[cur].right, m + 1, r, ql, qr));
	}

  public:
	SparseSegtree(int n, int q = 0) : n(n) {
		if (q > 0) { tree.reserve(2 * q * __lg(n)); }
		tree.push_back(Node());
	}

	void range_set(int ql, int qr, int val) { range_set(0, 0, n - 1, ql, qr, val); }

	int range_sum(int ql, int qr) { return range_sum(0, 0, n - 1, ql, qr); }
};

int main() {
	int query_num;
	cin >> query_num;
	const int RANGE_SIZE = 1e9;
	SparseSegtree st(RANGE_SIZE + 1, query_num);

	int c = 0;
	for (int i = 0; i < query_num; i++) {
		int type, x, y;
		cin >> type >> x >> y;
		if (type == 1) {
			c = st.range_sum(x + c, y + c);
			cout << c << '\n';
		} else if (type == 2) {
			st.range_set(x + c, y + c, 1);
		}
	}
}
```

It's possible to reduce the memory of a sparse segment tree to $\mathcal{O}(Q)$,
as described [here](https://codeforces.com/blog/entry/83969).

### Problems

Some of these problems are solvable with a normal segment tree if you use
coordinate compression. Sparse segment trees are rarely ever _required_ to solve
a particular problem, but they can make things a lot more convenient.

You should already have done this problem in
[Point Update Range Sum](https://usaco.guide/gold/PURS), but here we'll present two more
approaches. Both run in $\mathcal{O}(Q\sqrt N)$ time.

	- **27 - Square Root Algorithms** (CPH) —
		Blocking, Mo's Algo

## Blocking

<!-- partitioning into sqrt blocks (each block can have some sort of data structure ...)
 -->

We partition the array into blocks of size $\texttt{block\_size}=\lceil \sqrt{N}
\rceil$. Each block stores the sum of elements within it, and allows for the
creation of corresponding `update` and `query` operations.

**Update Queries:** $\mathcal{O}(1)$

To update an element at location $x$, first find the corresponding block using
the formula $\frac{x}{\texttt{block\_size}}$.

Then, apply the corresponding difference between the element currently stored at
$x$ and the element we want to change it to.

**Sum Queries:** $\mathcal{O}(\sqrt{N})$

To perform a sum query from $[0\ldots r]$, calculate

$$
\sum_{i = 0}^{R-1} \texttt{blocks}[i] + \sum_{R \cdot \texttt{block\_size}}^r \texttt{nums}[i]
$$

where $\texttt{blocks}[i]$ represents the total sum of the $i$-th block, the
$i$-th block represents the sum of the elements from the range $[i\cdot
\texttt{block\_size},(i + 1)\cdot \texttt{block\_size})$, and $R=\left\lceil
\frac{r}{\texttt{block\_size}} \right\rceil$.

Finally, $\sum_{i=l}^{r} \texttt{nums}[i]$ is the difference between the two
sums $\sum_{i=0}^{r}\texttt{nums}[i]$ and $\sum_{i=0}^{l-1}\texttt{nums}[i]$,
which each are calculated in $\mathcal{O}(\sqrt N)$.

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Sqrt {
	int block_size;
	vector<int> nums;
	vector<long long> blocks;
	Sqrt(int sqrtn, vector<int> &arr) : block_size(sqrtn), blocks(sqrtn, 0) {
		nums = arr;
		for (int i = 0; i < nums.size(); i++) { blocks[i / block_size] += nums[i]; }
	}

	/** O(1) update to set nums[x] to v */
	void update(int x, int v) {
		blocks[x / block_size] -= nums[x];
		nums[x] = v;
		blocks[x / block_size] += nums[x];
	}

	/** O(sqrt(n)) query for sum of [0, r) */
	long long query(int r) {
		long long res = 0;
		for (int i = 0; i < r / block_size; i++) { res += blocks[i]; }
		for (int i = (r / block_size) * block_size; i < r; i++) { res += nums[i]; }
		return res;
	}

	/** O(sqrt(n)) query for sum of [l, r) */
	long long query(int l, int r) { return query(r) - query(l - 1); }
};

int main() {
	int n, q;
	cin >> n >> q;

	vector<int> arr(n);
	for (int i = 0; i < n; i++) { cin >> arr[i]; }
	Sqrt sq((int)ceil(sqrt(n)), arr);

	for (int i = 0; i < q; i++) {
		int t, l, r;
		cin >> t >> l >> r;
		if (t == 1) {
			sq.update(l - 1, r);
		} else {
			cout << sq.query(l, r) << "\n";
		}
	}
}
```

## Combining Algorithms

Doing this problem with DP has a time complexity of $\mathcal{O}(N^2)$.

```cpp
vector<int> dp(n, 1);
for (int i = n - 1; i >= 0; i--) {
	for (int x = i + a[i]; x <= n; x += a[i]) { dp[i] = (dp[i] + dp[x]) % MOD; }
}
```

If we try prefix sums, the complexity is still $\mathcal{O}(N^2)$.

```cpp
for (int i = n - 1; i >= 0; i--) {
	dp[i] += s[a[i]][i % a[i]];
	dp[i] %= MOD;

	for (int j = 1; j <= x; j++) {
		s[j][i % j] += dp[i];
		s[j][i % j] %= MOD;
	}
}
```

We can apply the DP algorithm to the steps where $A_i \cdot x >= \sqrt(N)$ because the jump is bigger, thus resulting in a faster loop
We can apply prefix sums for the remaining cases where $A_i \cdot x < \sqrt(N)$.

This trick allows us to combine two $\mathcal{O}(N^2)$ algorithm into one $\mathcal{O}(N\sqrt(N))$ algorithm.

```cpp
#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

int main() {
	int n;
	cin >> n;
	vector<int> a(n);
	for (int i = 0; i < n; i++) { cin >> a[i]; }

	int x = (int)sqrt(n);

	vector<int> dp(n, 1);
	vector<vector<int>> s(x + 1, vector<int>(x + 1));
	for (int i = n - 1; i >= 0; i--) {
		if (a[i] > x) {
			for (int j = i + a[i]; j < n; j += a[i]) {
				dp[i] += dp[j];
				dp[i] %= MOD;
			}
		} else {
			dp[i] += s[a[i]][i % a[i]];
			dp[i] %= MOD;
		}
		for (int j = 1; j <= x; j++) {
			s[j][i % j] += dp[i];
			s[j][i % j] %= MOD;
		}
	}

	cout << dp[0] << endl;
}
```

## Batching

See the CPH section on [batch processing](https://usaco.guide/CPH.pdf#page=263).

Maintain a "buffer" of the latest updates (up to $\sqrt N$). The answer for each
sum query can be calculated with prefix sums and by examining each update within
the buffer. When the buffer gets too large ($\ge \sqrt N$), clear it and
recalculate prefix sums.

```cpp
#include <bits/stdc++.h>
using namespace std;

int n, q;
vector<int> arr;
vector<long long> prefix;

/** Build the prefix array for arr */
void build() {
	prefix[0] = 0;
	for (int i = 1; i <= n; i++) { prefix[i] = prefix[i - 1] + arr[i - 1]; }
}

int main() {
	cin >> n >> q;
	arr.resize(n);
	for (int i = 0; i < n; i++) { cin >> arr[i]; }
	prefix.assign(n + 1, 0);
	build();

	vector<pair<int, int>> updates;
	for (int i = 0; i < q; i++) {
		int type, a, b;
		cin >> type >> a >> b;
		if (type == 1) {
			a--;
			updates.push_back({a, b - arr[a]});
			arr[a] = b;
		} else {
			long long ans = prefix[b] - prefix[a - 1];
			a--, b--;
			for (const auto &[idx, val] : updates) {
				if (a <= idx && idx <= b) { ans += val; }
			}
			cout << ans << "\n";
		}

		// rebuild the prefix array once the buffer gets to sqrt(n)
		if (updates.size() * updates.size() >= n) {
			updates.clear();
			build();
		}
	}
}
```

## Mo's Algorithm

	- [Mo](https://codeforces.com/blog/entry/7383) (CF) — <i>very</i> brief description
	- [Mo](https://www.hackerearth.com/practice/notes/mos-algorithm/) (HE) — elaborate description with proof
	- [Mo](https://usaco.guide//CPH.pdf#page=265) (CPH) —

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Query {
	int l, r, idx;
};

int main() {
	int n;
	cin >> n;
	vector<int> v(n);
	for (int i = 0; i < n; i++) { cin >> v[i]; }

	int q;
	cin >> q;
	vector queries;
	for (int i = 0; i < q; i++) {
		int x, y;
		cin >> x >> y;
		queries.push_back({--x, --y, i});
	}

	int block_size = (int)sqrt(n);
	auto mo_cmp = [&](Query a, Query b) {
		int block_a = a.l / block_size;
		int block_b = b.l / block_size;
		if (block_a == block_b) { return a.r < b.r; }
		return block_a < block_b;
	};
	sort(queries.begin(), queries.end(), mo_cmp);

	int different_values = 0;
	vector<int> values(VALMAX);
	auto remove = [&](int idx) {
		values[v[idx]]--;
		if (values[v[idx]] == 0) { different_values--; }
	};
	auto add = [&](int idx) {
		values[v[idx]]++;
		if (values[v[idx]] == 1) { different_values++; }
	};

	int mo_left = -1;
	int mo_right = -1;
	vector<int> ans(q);
	for (int i = 0; i < q; i++) {
		int left = queries[i].l;
		int right = queries[i].r;

		while (mo_left < left) { remove(mo_left++); }
		while (mo_left > left) { add(--mo_left); }
		while (mo_right < right) { add(++mo_right); }
		while (mo_right > right) { remove(mo_right--); }

		ans[queries[i].idx] = different_values;
	}

	for (int i = 0; i < q; i++) { cout << ans[i] << '\n'; }
}
```

