```cpp
int N, h[750][750];
ll ans;
vector<pair<int, pi>> v;

int hsh(int a, int b) { return N * a + b; }

const int xd[4] = {1, 0, -1, 0}, yd[4] = {0, 1, 0, -1};

template <int SZ> struct DSU {
	int par[SZ], sz[SZ], measure[SZ];
	vi comp[SZ];
	DSU() { F0R(i, SZ) par[i] = i, sz[i] = 1, measure[i] = 1; }
	bool valid(int b, int c) { return b >= 0 && b < N && c >= 0 && c < N; }
	bool ok(int a, int b, int c) {
		if (!valid(b, c)) return 0;
		return par[hsh(b, c)] == a;
	}
	void addPoint(int x, pi t) {
		par[hsh(t.f, t.s)] = x;
		measure[x]++;
		F0R(i, 4) {
			if (ok(x, t.f + xd[i], t.s + yd[i])) {
				measure[x]--;
				int j = (i + 1) % 4;
				if (ok(x, t.f + xd[j], t.s + yd[j]) &&
				    ok(x, t.f + xd[j] + xd[i], t.s + yd[j] + yd[i]))
					measure[x]++;
			}
		}
		comp[x].pb(hsh(t.f, t.s));
	}
	void unite(pi x, pi y) {  // union-by-rank
		int X = hsh(x.f, x.s), Y = hsh(y.f, y.s);
		if (par[X] == par[Y]) return;
		X = par[X], Y = par[Y];
		if (sz(comp[X]) < sz(comp[Y])) swap(X, Y);
		trav(t, comp[Y]) addPoint(X, {t / N, t % N});
		comp[Y].clear();
	}
};

DSU<750 * 750> D;
bool ok[750][750];

void solve(int x, int y) {
	ok[x][y] = 1;
	F0R(i, 4) {
		int X = x + xd[i], Y = y + yd[i];
		if (X < 0 || X >= N || Y < 0 || Y >= N) continue;
		if (!ok[X][Y]) continue;
		D.unite({x, y}, {X, Y});
	}
}

int main() {
	setIO("valleys");
	re(N);
	F0R(i, N) F0R(j, N) {
		re(h[i][j]);
		v.pb({h[i][j], {i, j}});
		D.comp[hsh(i, j)].pb(hsh(i, j));
	}
	sort(all(v));
	F0R(i, sz(v)) {
		solve(v[i].s.f, v[i].s.s);
		pi p = v[i].s;
		int q = D.par[hsh(p.f, p.s)];
		if (D.measure[q] == 1) ans += sz(D.comp[q]);
	}
	cout << ans;
}
```

## Problems

## Euclidean Algorithm

	- [Euclidean](https://usaco.guide/algebra/euclid-algorithm.html) (cp-algo) —

The original Euclidean Algorithm computes $\gcd(a,b)$ and looks like this:

```cpp
ll euclid(ll a, ll b) {
	while (b > 0) {
		ll k = a / b;
		a -= k * b;
		swap(a, b);
	}
	return a;
}
```

## Extended Euclidean Algorithm

	- [Extended Euclidean](algebra/extended-euclid-algorithm.html) (cp-algo)
	- [Extended Euclidean](https://en.wikipedia.org/wiki/Extended_Euclidean_algorithm) (Wikipedia)
	- [Linear Diophantine Equation](algebra/linear-diophantine-equation.html) (cp-algo)

The extended Euclidean algorithm computes integers $x$ and $y$ such that

$$
ax+by=\gcd(a,b)
$$

We can slightly modify the version of the Euclidean algorithm given above to
return more information!

```cpp
array<ll, 3> extend_euclid(ll a, ll b) {
	// we know that (1 * a) + (0 * b) = a and (0 * a) + (1 * b) = b
	array<ll, 3> x = {1, 0, a};
	array<ll, 3> y = {0, 1, b};

	// run extended Euclidean algo
	while (y[2] > 0) {
		// keep subtracting multiple of one equation from the other
		ll k = x[2] / y[2];
		for (int i = 0; i < 3; i++) { x[i] -= k * y[i]; }
		swap(x, y);
	}
	return x;  // x[0] * a + x[1] * b = x[2], x[2] = gcd(a, b)
}
```

### Recursive Version

```cpp
ll euclid(ll a, ll b) {
	if (b == 0) { return a; }
	return euclid(b, a % b);
}
```

becomes

```cpp
pl extend_euclid(ll a, ll b) {  // returns {x,y}
	if (b == 0) { return {1, 0}; }
	pl p = extend_euclid(b, a % b);
	return {p.s, p.f - a / b * p.s};
}
```

The pair will equal to the first two returned elements of the array in the
iterative version. Looking at this version, we can prove by induction that when
$a$ and $b$ are distinct positive integers, the returned pair $(x,y)$ will
satisfy $|x|\le \frac{b}{2\gcd(a,b)}$ and $|y|\le \frac{a}{2\gcd(a,b)}$.
Furthermore, there can only exist one pair that satisfies these conditions!

Note that this works when $a,b$ are quite large (say, $\approx 2^{60}$) and we
won't wind up with overflow issues.

## Application - Modular Inverse

