	re(N, M);
	F0R(i, M) {
		str s;
		int A, B;
		re(s, A, B);
		if (s == "add") {
			add(A, B);
		} else if (s == "rem") {
			rem(A, B);
		} else {
			if (con(A, B)) ps("YES");
			else ps("NO");
		}
	}
}
