int main() {
	int n, m, q;
	while (cin >> n >> m >> q) {
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				dist[i][j] = (i == j ? 0 : INT_MAX);
				bad[i][j] = 0;
			}
		}

		for (int i = 0; i < m; i++) {
			int u, v, w;
			cin >> u >> v >> w;
			dist[u][v] = std::min(dist[u][v], (ll)w);
		}

		for (int k = 0; k < n; k++) {
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					if (dist[i][k] != INT_MAX && dist[k][j] != INT_MAX) {
						dist[i][j] = std::min(dist[i][j], dist[i][k] + dist[k][j]);
					}
				}
			}
		}

		for (int k = 0; k < n; k++) {
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					if (dist[i][k] != INT_MAX && dist[k][j] != INT_MAX &&
					    dist[i][j] > dist[i][k] + dist[k][j]) {
						bad[i][j] = 1;
					}
				}
			}
		}

		for (int k = 0; k < n; k++) {
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					if (dist[i][k] < INT_MAX && bad[k][j]) { bad[i][j] = 1; }
					if (dist[k][j] < INT_MAX && bad[i][k]) { bad[i][j] = 1; }
