			}
		}

		for (int i = 0; i < q; i++) {
			int u, v;
			cin >> u >> v;
			if (bad[u][v]) {
				cout << "-Infinity" << '\n';
			} else if (dist[u][v] == INT_MAX) {
				cout << "Impossible" << '\n';
			} else {
				cout << dist[u][v] << '\n';
			}
		}
		cout << '\n';
	}
}
