s: input strings
down: link tree of automaton
v: information regarding which cow each node belongs to
c: child array of automaton
l: link (of automaton)
d: depth (of automaton)
topo: toposort (of automaton)
T, X: counters for toposort and automaton
f: answer
cnt: number of ways to reach a node from the root
u: visited array for toposort
*/

// add cow b to value a
// value = -1: no cow assigned
// value = -2: multiple cows assigned
// value = 0..N: cow id
void merge(int &a, int b) {
	if (!~a) a = b;
	else if (~b && a != b) a = -2;
}

// template automaton code
int append(int p, char x) {
	if (~c[p][x]) {
		int q = c[p][x];
		if (d[q] == d[p] + 1) return q;
		else {
			++X;
			for (int i = 0; i < 26; ++i) c[X][i] = c[q][i];
			l[X] = l[q], d[X] = d[p] + 1;
			l[q] = X;
			for (; ~p && c[p][x] == q; p = l[p]) c[p][x] = l[q];
			return l[q];
		}
	}
	int n = ++X;
	d[n] = d[p] + 1;
	for (; ~p && !~c[p][x]; p = l[p]) c[p][x] = n;
	if (!~p) l[n] = 0;
	else {
		int q = c[p][x];
		if (d[q] == d[p] + 1) l[n] = q;
		else {
			++X;
			for (int i = 0; i < 26; ++i) c[X][i] = c[q][i];
			l[X] = l[q], d[X] = d[p] + 1;
			l[n] = l[q] = X;
			for (; ~p && c[p][x] == q; p = l[p]) c[p][x] = l[q];
		}
	}
	return n;
}

// DFS along links
void dfs2(int n = 0) {
	for (int x : down[n]) {
		dfs2(x);
		merge(v[n], v[x]);
	}
}
// DFS along suffix automaton. This builds the toposort
void dfs(int n = 0) {
	u[n] = 1;
	for (int i = 0; i < 26; ++i) {
		int y = c[n][i];
		if (~y && !u[y]) dfs(y);
	}
	topo[T++] = n;
}

int main(void) {
	IN = fopen("standingout.in", "r"), OUT = fopen("standingout.out", "w");
	memset(v, -1, sizeof v);
	memset(c, -1, sizeof c);
	fscanf(IN, "%d", &N);
	d[0] = 0, l[0] = -1;
	for (int i = 0; i < N; ++i) {
		fscanf(IN, " %s", s);
		int n = 0;
		for (int j = 0; s[j]; ++j) {
			n = append(n, s[j] - 'a');  // build automaton
			merge(v[n], i);
		}
	}
	// build link tree
	for (int i = 1; i <= X; ++i) down[l[i]].push_back(i);
	dfs();   // dfs link tree
	dfs2();  // dfs automaton
	cnt[0] = 1;
	for (int i = T - 1, x; i >= 0; --i) {
		x = topo[i];
		for (int j = 0; j < 26; ++j)
			if (~c[x][j])
				cnt[c[x][j]] += cnt[x];  // count number of paths from root to a node
		if (v[x] >= 0)
			f[v[x]] += cnt[x];  // if this node is associated with a unique cow,
			                    // add to answer
	}
	for (int i = 0; i < N; ++i) fprintf(OUT, "%lld\n", f[i]);
	return 0;
}
```

