using std::cout;
using std::endl;
using std::vector;

int main() {
	int n = 50;  // adjust n as you please
	vector<char> str;
	for (int i = 0; i < n; i++) { str.push_back('a' + rand() % 26); }

	for (char c : str) { cout << c; }
	cout << '\n';

